/**
 * Stripe → Mailchimp connector
 * When a Stripe checkout.session.completed webhook fires, add/update the customer
 * in a Mailchimp audience with the plan name as a tag.
 */

export interface ConnectorConfig {
  /** Secret used to verify the Stripe webhook signature (from STRIPE_WEBHOOK_SECRET). */
  stripeWebhookSecret: string
  /** Mailchimp API key (from MAILCHIMP_API_KEY). */
  mailchimpApiKey: string
  /** Mailchimp audience / list ID. */
  mailchimpListId: string
  /** Mailchimp server prefix, e.g. "us1" for us1.api.mailchimp.com. */
  mailchimpServerPrefix: string
  /** Raw request body for signature verification (optional in tests). */
  rawRequestBody?: string
  /** Value of the stripe-signature header (optional in tests). */
  stripeSignatureHeader?: string
  /** Injected fetch for testing. */
  fetch?: typeof fetch
}

export interface StripeWebhookPayload {
  id: string
  type: string
  data: {
    object: {
      id: string
      customer: string
      customer_email: string
      metadata?: {
        plan?: string
      }
      subscription?: string
    }
  }
}

export interface ConnectorResult {
  mailchimpMemberId: string
  email: string
  plan: string
}

/** Verify Stripe webhook signature using HMAC-SHA256 (Web Crypto API). */
async function verifyStripeSignature(
  secret: string,
  signatureHeader: string,
  rawBody: string,
): Promise<void> {
  // Parse header: "t=1234567890,v1=abc123,v0=def456"
  const parts = signatureHeader.split(',').map((p) => p.trim())
  let timestamp = ''
  let signature = ''
  for (const part of parts) {
    if (part.startsWith('t=')) timestamp = part.slice(2)
    else if (part.startsWith('v1=')) signature = part.slice(3)
  }
  if (!timestamp || !signature) {
    throw new Error('Invalid stripe-signature header format')
  }

  const message = `${timestamp}.${rawBody}`
  const encoder = new TextEncoder()
  const keyData = encoder.encode(secret)
  const messageData = encoder.encode(message)

  // Import secret as HMAC key
  const cryptoKey = await crypto.subtle.importKey(
    'raw',
    keyData,
    { name: 'HMAC', hash: 'SHA-256' },
    false,
    ['sign'],
  )

  // Sign message
  const sigBytes = await crypto.subtle.sign('HMAC', cryptoKey, messageData)
  const sigHex = Array.from(new Uint8Array(sigBytes))
    .map((b) => b.toString(16).padStart(2, '0'))
    .join('')

  // Constant-time comparison
  if (sigHex.length !== signature.length) {
    throw new Error('Stripe signature verification failed')
  }
  let diff = 0
  for (let i = 0; i < sigHex.length; i++) {
    diff |= sigHex.charCodeAt(i) ^ signature.charCodeAt(i)
  }
  if (diff !== 0) {
    throw new Error('Stripe signature verification failed')
  }
}

/** Call Mailchimp API with bearer auth. */
async function mailchimpRequest(
  config: ConnectorConfig,
  method: string,
  path: string,
  body?: unknown,
): Promise<Response> {
  const url = `https://${config.mailchimpServerPrefix}.api.mailchimp.com/3.0${path}`
  const headers: Record<string, string> = {
    Authorization: `Bearer ${config.mailchimpApiKey}`,
    'Content-Type': 'application/json',
  }
  const fetchFn = config.fetch ?? fetch
  const res = await fetchFn(url, {
    method,
    headers,
    body: body ? JSON.stringify(body) : undefined,
  })
  if (!res.ok) {
    throw new Error(`Mailchimp API error: ${res.status} ${res.statusText} for ${method} ${path}`)
  }
  return res
}

export async function handle(
  payload: StripeWebhookPayload,
  config: ConnectorConfig,
): Promise<ConnectorResult> {
  // 1. Validate input
  if (payload.type !== 'checkout.session.completed') {
    throw new Error(`Expected checkout.session.completed event, got ${payload.type}`)
  }
  const session = payload.data?.object
  if (!session) throw new Error('Missing data.object in payload')
  const email = session.customer_email
  if (!email) throw new Error('Missing customer_email in session object')

  // 2. Extract plan name
  let plan = session.metadata?.plan
  if (!plan) {
    // Fallback would require expanding subscription; not in example payload.
    throw new Error('Missing plan name: metadata.plan not present and subscription expansion not implemented')
  }

  // 3. Verify Stripe signature if header and raw body provided
  if (config.stripeSignatureHeader && config.rawRequestBody) {
    await verifyStripeSignature(config.stripeWebhookSecret, config.stripeSignatureHeader, config.rawRequestBody)
  }

  // 4. Upsert member in Mailchimp (POST /lists/{list_id}/members)
  const listPath = `/lists/${config.mailchimpListId}/members`
  const requestBody = {
    email_address: email,
    status_if_new: 'subscribed',
    tags: [plan],
  }
  const res = await mailchimpRequest(config, 'POST', listPath, requestBody)
  const data = (await res.json()) as { id: string; email_address: string }

  return {
    mailchimpMemberId: data.id,
    email: data.email_address,
    plan,
  }
}

import { describe, it, expect, vi } from 'vitest'
import { handle, ConnectorConfig, StripeWebhookPayload } from './connector'
import {
  SOURCE_EXAMPLE,
  TARGET_ENDPOINTS,
  contractFetch,
  fakeFetch,
  jsonResponse,
  RecordedCall,
} from './fixtures'

// ---- Contract test (must be at top level, title exactly 'contract') ----
describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      stripeWebhookSecret: 'whsec_test',
      mailchimpApiKey: 'test-key-us1',
      mailchimpListId: 'list_123',
      mailchimpServerPrefix: 'us1',
      fetch,
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as StripeWebhookPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.mailchimpMemberId).toBe('abc123')
    expect(result.email).toBe('customer@example.com')
    expect(result.plan).toBe('pro')
  })
})

// ---- Helper to build a valid config for unit tests ----
function testConfig(overrides: Partial<ConnectorConfig> = {}): ConnectorConfig {
  return {
    stripeWebhookSecret: 'whsec_test',
    mailchimpApiKey: 'test-key-us1',
    mailchimpListId: 'list_123',
    mailchimpServerPrefix: 'us1',
    ...overrides,
  }
}

// ---- Unit tests ----
describe('handle', () => {
  it('happy path: creates member with correct fields and auth', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      expect(req.method).toBe('POST')
      expect(req.url).toContain('/lists/list_123/members')
      expect(req.headers.get('authorization')).toBe('Bearer test-key-us1')
      const body = req.json as { email_address: string; status_if_new: string; tags: string[] }
      expect(body.email_address).toBe('customer@example.com')
      expect(body.status_if_new).toBe('subscribed')
      expect(body.tags).toEqual(['pro'])
      return jsonResponse({ id: 'abc123', email_address: 'customer@example.com' }, 201)
    })

    const payload: StripeWebhookPayload = {
      id: 'evt_1',
      type: 'checkout.session.completed',
      data: {
        object: {
          id: 'cs_1',
          customer: 'cus_1',
          customer_email: 'customer@example.com',
          metadata: { plan: 'pro' },
        },
      },
    }

    const result = await handle(payload, testConfig({ fetch }))
    expect(result.mailchimpMemberId).toBe('abc123')
    expect(result.email).toBe('customer@example.com')
    expect(result.plan).toBe('pro')
    expect(calls.length).toBe(1)
  })

  it('uses injected fetch and records call', async () => {
    const { fetch, calls } = fakeFetch((req) => jsonResponse({ id: 'mem_1', email_address: 'a@b.c' }, 201))
    const payload: StripeWebhookPayload = {
      id: 'evt_2',
      type: 'checkout.session.completed',
      data: { object: { id: 'cs_2', customer: 'cus_2', customer_email: 'a@b.c', metadata: { plan: 'basic' } } },
    }
    await handle(payload, testConfig({ fetch }))
    expect(calls[0].method).toBe('POST')
    expect(calls[0].json).toEqual({ email_address: 'a@b.c', status_if_new: 'subscribed', tags: ['basic'] })
  })

  it('throws on missing customer_email', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 201))
    const payload = {
      id: 'evt_3',
      type: 'checkout.session.completed',
      data: { object: { id: 'cs_3', customer: 'cus_3', metadata: { plan: 'pro' } } },
    } as unknown as StripeWebhookPayload
    await expect(handle(payload, testConfig({ fetch }))).rejects.toThrow('Missing customer_email')
  })

  it('throws on missing metadata.plan', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 201))
    const payload: StripeWebhookPayload = {
      id: 'evt_4',
      type: 'checkout.session.completed',
      data: { object: { id: 'cs_4', customer: 'cus_4', customer_email: 'x@y.z', metadata: {} } },
    }
    await expect(handle(payload, testConfig({ fetch }))).rejects.toThrow('Missing plan name')
  })

  it('throws on wrong event type', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 201))
    const payload: StripeWebhookPayload = {
      id: 'evt_5',
      type: 'invoice.paid',
      data: { object: { id: 'cs_5', customer: 'cus_5', customer_email: 'x@y.z', metadata: { plan: 'pro' } } },
    }
    await expect(handle(payload, testConfig({ fetch }))).rejects.toThrow('Expected checkout.session.completed')
  })

  it('throws on non-2xx Mailchimp response with status and endpoint', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ error: 'Invalid list' }, 404))
    const payload: StripeWebhookPayload = {
      id: 'evt_6',
      type: 'checkout.session.completed',
      data: { object: { id: 'cs_6', customer: 'cus_6', customer_email: 'x@y.z', metadata: { plan: 'pro' } } },
    }
    await expect(handle(payload, testConfig({ fetch }))).rejects.toThrow('Mailchimp API error: 404 Not Found for POST /lists/list_123/members')
  })

  it('verifies Stripe signature when header and raw body provided', async () => {
    // Use a known secret and body to produce a valid signature
    const secret = 'whsec_test'
    const rawBody = JSON.stringify(SOURCE_EXAMPLE)
    // Compute signature using Web Crypto (same as connector)
    const encoder = new TextEncoder()
    const keyData = encoder.encode(secret)
    const cryptoKey = await crypto.subtle.importKey('raw', keyData, { name: 'HMAC', hash: 'SHA-256' }, false, ['sign'])
    const timestamp = '1234567890'
    const message = `${timestamp}.${rawBody}`
    const sigBytes = await crypto.subtle.sign('HMAC', cryptoKey, encoder.encode(message))
    const sigHex = Array.from(new Uint8Array(sigBytes)).map((b) => b.toString(16).padStart(2, '0')).join('')
    const signatureHeader = `t=${timestamp},v1=${sigHex}`

    const { fetch, calls } = fakeFetch((req) => jsonResponse({ id: 'mem_7', email_address: 'customer@example.com' }, 201))

    const payload = SOURCE_EXAMPLE as unknown as StripeWebhookPayload
    const result = await handle(payload, testConfig({ fetch, rawRequestBody: rawBody, stripeSignatureHeader: signatureHeader }))
    expect(result.mailchimpMemberId).toBe('mem_7')
    expect(calls.length).toBe(1)
  })

  it('throws on invalid Stripe signature', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 201))
    const payload = SOURCE_EXAMPLE as unknown as StripeWebhookPayload
    await expect(
      handle(payload, testConfig({ fetch, rawRequestBody: '{}', stripeSignatureHeader: 't=123,v1=bad' })),
    ).rejects.toThrow('Stripe signature verification failed')
  })
})

